    expect(parseStepLines('pull 0 2026-09-28T22:13:02Z\n\nshift 3 2026-09-28T22:40:00Z\n')).toEqual([
      { name: 'pull', exit: 0, at: '2026-09-28T22:13:02.000Z' },
      { name: 'shift', exit: 3, at: '2026-09-28T22:40:00.000Z' },
